from __future__ import annotations

from fastapi import APIRouter, Request
from fastapi.responses import HTMLResponse

from .branding import ENDORSEMENT, PRODUCT_NAME

router = APIRouter()


@router.get("/social-house", response_class=HTMLResponse)
def social_house(request: Request):
    member = getattr(request.state, "member", None)
    plan = getattr(getattr(member, "plan", None), "id", "member")
    html = r"""<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1,viewport-fit=cover'><meta name='theme-color' content='#05040b'><title>__PRODUCT__ — Social Media Management House</title><style>
:root{--bg:#03040a;--panel:#0d0f1b;--panel2:#12162a;--line:#ffffff1c;--gold:#f3c76d;--violet:#a76cff;--cyan:#5ce8ff;--pink:#ff72cd;--green:#7ce0aa;--muted:#b7bbce;--text:#fff}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 8% 0,#321049,transparent 30%),radial-gradient(circle at 95% 8%,#0b3952,transparent 28%),linear-gradient(#03040a,#070811 65%,#020309);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;min-height:100vh}a{color:inherit;text-decoration:none}button,input,textarea,select{font:inherit}.wrap{width:min(1450px,calc(100% - 28px));margin:auto}.nav{position:sticky;top:0;z-index:10;background:#05060be8;backdrop-filter:blur(18px);border-bottom:1px solid var(--line)}.navin{min-height:72px;display:flex;align-items:center;justify-content:space-between;gap:16px}.brand{display:flex;gap:10px;align-items:center;font-weight:950}.brand img{width:46px;height:46px;border-radius:14px;border:1px solid #ffffff2a}.brand small{display:block;color:var(--gold);font-size:.62rem;text-transform:uppercase;letter-spacing:.07em}.navlinks,.actions{display:flex;gap:7px;flex-wrap:wrap}.btn{border:1px solid var(--line);background:#ffffff08;color:#fff;border-radius:12px;padding:9px 12px;font-weight:800;cursor:pointer}.btn.primary{border:0;background:linear-gradient(115deg,#fff0ad,var(--gold),#c39aff);color:#180d20}.btn.small{font-size:.72rem;padding:6px 8px}.hero{padding:44px 0 24px}.eyebrow{color:var(--gold);font-size:.72rem;font-weight:950;letter-spacing:.17em;text-transform:uppercase}.hero h1{font-size:clamp(2.7rem,6vw,5.4rem);letter-spacing:-.055em;line-height:.92;margin:.14em 0 .2em}.hero h1 span{background:linear-gradient(95deg,#fff,var(--gold),var(--pink),var(--cyan));background-clip:text;color:transparent}.lead{color:var(--muted);max-width:980px;line-height:1.6}.statusline{display:flex;gap:8px;flex-wrap:wrap;margin-top:16px}.chip{border:1px solid var(--line);border-radius:999px;padding:6px 9px;font-size:.72rem;color:#ddd}.chip.good{color:var(--green);border-color:#7ce0aa40}.layout{display:grid;grid-template-columns:260px 1fr;gap:14px;padding-bottom:60px}.sidebar,.panel{border:1px solid var(--line);background:linear-gradient(145deg,#101323de,#080a14eb);border-radius:21px;padding:16px}.sidebar{height:max-content;position:sticky;top:88px}.sidebar h3{margin:3px 0 12px}.space{border:1px solid var(--line);border-radius:12px;padding:10px;margin:7px 0;background:#ffffff05;cursor:pointer}.space.active{border-color:#f3c76d60;background:#f3c76d0a}.tabs{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:14px}.tab{border:1px solid var(--line);border-radius:999px;padding:7px 10px;background:#ffffff05;cursor:pointer;font-size:.8rem;font-weight:800}.tab.active{background:#ffffff12;border-color:#ffffff3a}.field{width:100%;border:1px solid var(--line);background:#070913;color:#fff;border-radius:11px;padding:10px;outline:none}.field:focus{border-color:#a76cff88}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.metric,.card{border:1px solid var(--line);background:#ffffff05;border-radius:16px;padding:14px}.metric b{font-size:1.5rem;display:block}.metric small,.muted{color:var(--muted)}.board{display:grid;grid-template-columns:repeat(4,minmax(220px,1fr));gap:10px;overflow:auto}.column{border:1px solid var(--line);border-radius:16px;padding:10px;background:#070914;min-height:280px}.column h4{margin:4px 0 10px}.post{border:1px solid var(--line);border-radius:13px;padding:11px;background:#111427;margin:8px 0}.post strong{display:block}.post small{color:var(--muted)}.platforms{margin:7px 0}.platforms span{display:inline-block;border:1px solid var(--line);border-radius:999px;font-size:.64rem;padding:3px 6px;margin:2px}.forms{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:12px}.formbox{border:1px solid var(--line);border-radius:16px;padding:13px;background:#ffffff04}.stack{display:grid;gap:8px}.row{display:grid;grid-template-columns:1fr 1fr;gap:8px}.empty{border:1px dashed #ffffff28;border-radius:14px;padding:20px;text-align:center;color:var(--muted)}.notice{display:none;border:1px solid var(--line);border-radius:12px;padding:10px 12px;margin-bottom:12px}.notice.show{display:block}.notice.error{border-color:#ff8f9d50;color:#ffd6dc}.featuregrid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.feature h4{margin:7px 0}.feature p{color:var(--muted);font-size:.86rem;line-height:1.5}.footer{border-top:1px solid var(--line);padding:28px 0 42px;color:var(--muted);font-size:.85rem}@media(max-width:1050px){.layout{grid-template-columns:1fr}.sidebar{position:relative;top:auto}.grid,.featuregrid{grid-template-columns:repeat(2,1fr)}}@media(max-width:680px){.grid,.featuregrid,.forms,.row{grid-template-columns:1fr}.board{grid-template-columns:repeat(4,260px)}.navlinks .optional{display:none}.brand small{display:none}}
</style></head><body>
<nav class='nav'><div class='wrap navin'><a class='brand' href='/'><img src='/brand/pulsar-frequency-house-logo.svg' alt='logo'><span>__PRODUCT__<small>__ENDORSEMENT__</small></span></a><div class='navlinks'><a class='btn optional' href='/creative-house'>Creative House</a><a class='btn optional' href='/studio'>Music</a><a class='btn optional' href='/command-center'>ESP Hub</a><a class='btn' href='/dashboard'>Dashboard</a></div></div></nav>
<main class='wrap'><section class='hero'><div class='eyebrow'>Social Media Management House · Aura Social Intelligence</div><h1>Plan. Create. Approve. <span>Publish. Learn.</span></h1><p class='lead'>A multi-brand social command center built directly into Pulsar-Frequency House. Plan content across platforms, manage campaigns and tasks, keep brand personas isolated, repurpose Creative DNA assets, enforce approval gates and prepare for official-API publishing, analytics and community management.</p><div class='statusline'><span class='chip good'>✓ Multi-brand Social Houses</span><span class='chip good'>✓ Calendar/Board/Table data foundation</span><span class='chip good'>✓ Projects, Tasks & Notes</span><span class='chip good'>✓ Platform variants & validation</span><span class='chip good'>✓ Approval gates</span><span class='chip'>Publishing adapters require platform authorization</span><span class='chip'>Plan: __PLAN__</span></div></section><div id='notice' class='notice'></div>
<section class='layout'><aside class='sidebar'><div class='eyebrow'>Social Houses</div><h3>Brands & accounts</h3><div id='spaces'><div class='empty'>No Social Houses yet.</div></div><div class='stack' style='margin-top:12px'><input id='spaceName' class='field' placeholder='New brand / creator space'><button class='btn primary' onclick='createSpace()'>Create Social House</button></div></aside>
<section class='panel'><div class='tabs'><button class='tab active' data-tab='overview' onclick="showTab('overview',this)">Overview</button><button class='tab' data-tab='board' onclick="showTab('board',this)">Board</button><button class='tab' data-tab='calendar' onclick="showTab('calendar',this)">Calendar</button><button class='tab' data-tab='campaigns' onclick="showTab('campaigns',this)">Campaigns</button><button class='tab' data-tab='tasks' onclick="showTab('tasks',this)">Tasks</button><button class='tab' data-tab='persona' onclick="showTab('persona',this)">Aura Persona</button><button class='tab' data-tab='features' onclick="showTab('features',this)">Full Feature Map</button></div><div id='content'><div class='empty'>Choose or create a Social House.</div></div></section></section></main>
<footer class='footer'><div class='wrap'><strong>__PRODUCT__</strong> · Social Media Management House · __ENDORSEMENT__</div></footer>
<script>
let spaces=[],house=null,activeTab='overview';const qs=id=>document.getElementById(id);
function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function notice(m,e=false){const n=qs('notice');n.textContent=m;n.className='notice show'+(e?' error':'');clearTimeout(window._n);window._n=setTimeout(()=>n.className='notice',6500)}
async function api(p,o={}){const r=await fetch(p,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(o.headers||{})},...o});let b={};try{b=await r.json()}catch(e){}if(!r.ok)throw new Error(b.detail||`Request failed (${r.status})`);return b}
async function loadSpaces(){try{const d=await api('/social/spaces');spaces=d.spaces||[];renderSpaces();if(!house&&spaces.length)await loadHouse(spaces[0].id)}catch(e){notice(e.message,true)}}
function renderSpaces(){qs('spaces').innerHTML=spaces.length?spaces.map(s=>`<div class="space ${house?.id===s.id?'active':''}" onclick="loadHouse('${s.id}')"><strong>${esc(s.name)}</strong><div class="muted" style="font-size:.72rem">${esc(s.description||'Social House')}</div></div>`).join(''):'<div class="empty">No Social Houses yet.</div>'}
async function createSpace(){const name=qs('spaceName').value.trim();if(!name)return notice('Enter a brand or creator name.',true);try{house=await api('/social/spaces',{method:'POST',body:JSON.stringify({name})});qs('spaceName').value='';await loadSpaces();await loadHouse(house.id);notice('Social House created.')}catch(e){notice(e.message,true)}}
async function loadHouse(id){try{house=await api(`/social/spaces/${encodeURIComponent(id)}`);renderSpaces();renderTab()}catch(e){notice(e.message,true)}}
function showTab(t,el){activeTab=t;document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));el.classList.add('active');renderTab()}
function renderTab(){if(!house)return;const fn={overview:renderOverview,board:renderBoard,calendar:renderCalendar,campaigns:renderCampaigns,tasks:renderTasks,persona:renderPersona,features:renderFeatures}[activeTab]||renderOverview;qs('content').innerHTML=fn()}
function renderOverview(){const scheduled=house.content.filter(x=>['scheduled','publishing'].includes(x.status)).length,published=house.content.filter(x=>x.status==='published').length,pending=house.content.filter(x=>x.status==='pending_approval').length;return `<div class="grid"><div class="metric"><b>${house.content.length}</b><small>Content items</small></div><div class="metric"><b>${scheduled}</b><small>Scheduled</small></div><div class="metric"><b>${pending}</b><small>Awaiting approval</small></div><div class="metric"><b>${published}</b><small>Published confirmations</small></div></div><div class="forms" style="margin-top:12px"><div class="formbox"><h3>Quick content idea</h3><div class="stack"><input id="postTitle" class="field" placeholder="Post / content title"><div class="row"><select id="postPlatform" class="field"><option>tiktok</option><option>instagram</option><option>youtube</option><option>facebook</option><option>linkedin</option><option>threads</option><option>x</option><option>pinterest</option></select><select id="postType" class="field"><option>video</option><option>photo</option><option>reel</option><option>post</option><option>short</option><option>story</option></select></div><textarea id="postCaption" class="field" placeholder="Caption / Aura draft"></textarea><label class="muted"><input id="approvalRequired" type="checkbox"> Require approval before publishing</label><button class="btn primary" onclick="addContent()">Add content</button></div></div><div class="formbox"><h3>Creative pipeline</h3><p class="muted">A Social House can link a post back to music, video, image or voice Creative DNA. The next integration layer lets Aura turn a finished song/video/image into a complete launch campaign without downloading and re-uploading assets.</p><div class="actions"><a class="btn" href="/creative-house">Open Creative House</a><button class="btn" onclick="showFeatureMessage()">Aura campaign planner</button></div></div></div><div class="featuregrid"><div class="card feature"><div>🗓️</div><h4>Unified planning</h4><p>Board, calendar, campaigns, status workflows, platform variants and unscheduled ideas.</p></div><div class="card feature"><div>✅</div><h4>Approval safety</h4><p>Approval-required content cannot enter a future auto-publish queue until its gate is satisfied.</p></div><div class="card feature"><div>🧠</div><h4>Aura Social Persona</h4><p>Separate voice, audience, goals, content pillars, vocabulary and brand memory per Social House.</p></div></div>`}
async function addContent(){const title=qs('postTitle').value.trim();if(!title)return notice('Enter a content title.',true);const platform=qs('postPlatform').value,type=qs('postType').value;try{const d=await api(`/social/spaces/${house.id}/content`,{method:'POST',body:JSON.stringify({title,status:'idea',approval_required:qs('approvalRequired').checked,variants:[{platform,content_type:type,caption:qs('postCaption').value.trim(),hashtags:[],media_refs:[],auto_publish:false}]})});house=d.house;renderTab();notice('Content added to Social House.')}catch(e){notice(e.message,true)}}
function renderBoard(){const cols=['idea','in_production','pending_approval','approved'];return `<div class="board">${cols.map(s=>`<div class="column"><h4>${s.replaceAll('_',' ')}</h4>${house.content.filter(x=>x.status===s).map(card).join('')||'<div class="muted">No content</div>'}</div>`).join('')}</div>`}
function card(p){return `<div class="post"><strong>${esc(p.title)}</strong><div class="platforms">${(p.variants||[]).map(v=>`<span>${v.platform}</span>`).join('')}</div><small>${p.approval_required?'Approval required':'No approval gate'}</small></div>`}
function renderCalendar(){const dated=[];house.content.forEach(p=>(p.variants||[]).forEach(v=>{if(v.scheduled_at)dated.push({p,v})}));return `<h3>Content Calendar</h3><p class="muted">Scheduled platform variants appear here. Drag-and-drop and recurring content are part of the next UI phase.</p>${dated.length?dated.sort((a,b)=>String(a.v.scheduled_at).localeCompare(String(b.v.scheduled_at))).map(x=>`<div class="card" style="margin:8px 0"><strong>${esc(x.p.title)}</strong><div class="muted">${esc(x.v.platform)} · ${esc(x.v.scheduled_at)}</div></div>`).join(''):'<div class="empty">No scheduled variants yet.</div>'}`}
function renderCampaigns(){return `<div class="forms"><div class="formbox"><h3>Create campaign</h3><div class="stack"><input id="campaignName" class="field" placeholder="Campaign / project name"><textarea id="campaignDescription" class="field" placeholder="Brief or launch objective"></textarea><button class="btn primary" onclick="addCampaign()">Create campaign</button></div></div><div class="formbox"><h3>Campaigns</h3>${house.projects.length?house.projects.map(p=>`<div class="post"><strong>${esc(p.name)}</strong><small>${esc(p.description)}</small></div>`).join(''):'<div class="empty">No campaigns yet.</div>'}</div></div>`}
async function addCampaign(){const name=qs('campaignName').value.trim();if(!name)return notice('Enter a campaign name.',true);try{const d=await api(`/social/spaces/${house.id}/projects`,{method:'POST',body:JSON.stringify({name,description:qs('campaignDescription').value.trim(),tags:[]})});house=d.house;renderTab();notice('Campaign created.')}catch(e){notice(e.message,true)}}
function renderTasks(){return `<div class="forms"><div class="formbox"><h3>Add task</h3><div class="stack"><input id="taskTitle" class="field" placeholder="Task"><select id="taskPriority" class="field"><option>normal</option><option>high</option><option>urgent</option><option>low</option></select><button class="btn primary" onclick="addTask()">Add task</button></div></div><div class="formbox"><h3>Task list</h3>${house.tasks.length?house.tasks.map(t=>`<div class="post"><strong>${esc(t.title)}</strong><small>${esc(t.status)} · ${esc(t.priority)}</small></div>`).join(''):'<div class="empty">No tasks yet.</div>'}</div></div>`}
async function addTask(){const title=qs('taskTitle').value.trim();if(!title)return notice('Enter a task.',true);try{const d=await api(`/social/spaces/${house.id}/tasks`,{method:'POST',body:JSON.stringify({title,priority:qs('taskPriority').value})});house=d.house;renderTab();notice('Task added.')}catch(e){notice(e.message,true)}}
function renderPersona(){const p=house.persona||{};return `<div class="formbox"><h3>Aura Social Persona</h3><p class="muted">This memory is isolated to ${esc(house.name)} so Aura does not mix one brand/client voice with another.</p><div class="stack"><input id="personaNiche" class="field" placeholder="Niche / industry" value="${esc(p.niche||'')}"><input id="personaAudience" class="field" placeholder="Target audience" value="${esc(p.audience||'')}"><textarea id="personaVoice" class="field" placeholder="Brand voice">${esc(p.voice||'')}</textarea><textarea id="personaVisual" class="field" placeholder="Visual guidelines">${esc(p.visual_guidelines||'')}</textarea><input id="personaPillars" class="field" placeholder="Content pillars, comma separated" value="${esc((p.content_pillars||[]).join(', '))}"><textarea id="personaCTA" class="field" placeholder="CTA rules">${esc(p.cta_rules||'')}</textarea><button class="btn primary" onclick="savePersona()">Save Aura persona</button></div></div>`}
async function savePersona(){try{house=await api(`/social/spaces/${house.id}/persona`,{method:'PUT',body:JSON.stringify({brand_name:house.name,niche:qs('personaNiche').value.trim(),audience:qs('personaAudience').value.trim(),voice:qs('personaVoice').value.trim(),visual_guidelines:qs('personaVisual').value.trim(),content_pillars:qs('personaPillars').value.split(',').map(x=>x.trim()).filter(Boolean),cta_rules:qs('personaCTA').value.trim(),goals:[],preferred_vocabulary:[],prohibited_language:[],hashtag_banks:{},platform_priorities:[],posting_cadence:'',memory:{}})});renderTab();notice('Aura Social Persona saved.')}catch(e){notice(e.message,true)}}
function renderFeatures(){const f=[['🗓️','Planning','Calendar, board, table/list, drafts, unscheduled queue, recurring and multi-platform content.'],['📤','Scheduling & Auto Post','Official-API adapter layer with token health, approval gates, platform validation and publish audit trail.'],['🔁','Repurposing','Turn long-form video, music, Lives and creative assets into platform-native variants.'],['🗂️','Media Library','Folders, search, tags, crop/aspect ratios, Drive/Canva imports, provenance and asset usage history.'],['👁️','Native Previews','Instagram feed planner, TikTok/Reels/Stories/YouTube/LinkedIn/X/Threads previews.'],['✅','Approvals','Public review links, external feedback, internal comments, permissions, expiry and asset requests.'],['🧩','Projects & Tasks','Campaigns, briefs, tasks, templates, dependencies, assignees, roadmaps and workflows.'],['📊','Analytics','Normalized metrics, top posts, demographics where available, posting-time analysis and branded reports.'],['✨','Aura Social AI','Brand voice, captions, strategy, calendar creation, gap filling, repurposing, trend research and performance recommendations.'],['💬','Social Inbox','Comments/DMs/story replies where APIs permit, assignment, saved replies and Aura-assisted responses.'],['🔌','Integrations','Google Drive, Google Calendar, Canva, cloud media, notifications, webhooks and MCP-style control.'],['⚙️','Automations','Status-based actions, approval notifications, failure alerts, report generation and post-completion campaign generation.']];return `<div class="featuregrid">${f.map(x=>`<div class="card feature"><div>${x[0]}</div><h4>${x[1]}</h4><p>${x[2]}</p></div>`).join('')}</div>`}
function showFeatureMessage(){notice('Aura campaign-generation architecture is now part of the Social House roadmap; direct Creative DNA → campaign actions are the next integration phase.')}
loadSpaces();
</script></body></html>"""
    return HTMLResponse(html.replace('__PRODUCT__', PRODUCT_NAME).replace('__ENDORSEMENT__', ENDORSEMENT).replace('__PLAN__', plan.upper()))
